import{_ as e,c as d,o,b2 as a}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"客户端管理（OAuth Client + HMAC）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/modules/client-management.md","filePath":"docs/backend/modules/client-management.md"}'),c={name:"docs/backend/modules/client-management.md"};function i(l,t,r,n,s,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="客户端管理-oauth-client-hmac" tabindex="-1">客户端管理（OAuth Client + HMAC） <a class="header-anchor vp-link" href="#客户端管理-oauth-client-hmac" aria-label="Permalink to &quot;客户端管理（OAuth Client + HMAC）&quot;">​</a></h1><p>本项目的「客户端」指 <strong><code>sys_oauth_client</code></strong> 记录：同时承担 <strong>OAuth2 授权服务器客户端</strong> 与 <strong>API 调用方（HMAC 签名）</strong> 身份，不单独维护 access_token 用于管理端登录。</p><h2 id="管理接口" tabindex="-1">管理接口 <a class="header-anchor vp-link" href="#管理接口" aria-label="Permalink to &quot;管理接口&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysOauthClientController</code></td></tr><tr><td>路径</td><td><code>/system/oauthClient</code></td></tr><tr><td>前端</td><td><code>views/system/oauthClient/index.vue</code></td></tr></tbody></table></div><div class="vp-table"><table><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td>GET <code>/list</code></td><td>分页列表</td></tr><tr><td>GET <code>/{clientId}</code></td><td>详情</td></tr><tr><td>POST <code>/{clientId}/revealSecret</code></td><td>揭示密钥（一次性展示，需权限）</td></tr><tr><td>POST <code>/create</code>、<code>/update</code>、<code>/remove</code></td><td>CRUD</td></tr></tbody></table></div><h2 id="核心字段" tabindex="-1">核心字段 <a class="header-anchor vp-link" href="#核心字段" aria-label="Permalink to &quot;核心字段&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>client_id</code></td><td>调用方标识，对应请求头 <code>X-Client-Id</code></td></tr><tr><td><code>client_secret</code></td><td>SM4 加密存储；签名用明文</td></tr><tr><td><code>redirect_uris</code></td><td>OAuth 回调，精确匹配</td></tr><tr><td><code>grant_types</code></td><td>允许的授权模式</td></tr><tr><td><code>scopes</code></td><td>授权页 scope（openid/profile 等）</td></tr><tr><td><code>api_path_patterns</code></td><td>Open API / 签名请求的 <strong>Ant 路径</strong> 白名单（每行一条）</td></tr><tr><td><code>sign_verify</code></td><td><code>1</code> 强制 HMAC；<code>0</code> 跳过签名校验（Open API 仍校验 token+路径）</td></tr></tbody></table></div><h2 id="首方-quick-ui" tabindex="-1">首方 quick-ui <a class="header-anchor vp-link" href="#首方-quick-ui" aria-label="Permalink to &quot;首方 quick-ui&quot;">​</a></h2><p>Flyway <code>V28__oauth2_quick_ui_client.sql</code> 预置 <code>client_id=quick-ui</code>。前端构建注入：</p><ul><li><code>VITE_APP_CLIENT_ID</code></li><li><code>VITE_APP_CLIENT_SIGN_KEY</code></li></ul><p>详见 <a href="./oauth2.html" class="vp-link">OAuth2 集成</a>。</p><h2 id="签名校验流程" tabindex="-1">签名校验流程 <a class="header-anchor vp-link" href="#签名校验流程" aria-label="Permalink to &quot;签名校验流程&quot;">​</a></h2><ol><li>读取 <code>X-Client-Id</code>、Timestamp、Nonce、Signature</li><li>校验时间窗（默认 300s）与 nonce 防重放（<code>clientSignNonce#300</code> 缓存）</li><li>HMAC-SHA256 与 <code>ClientSignService.buildCanonical</code> 一致</li><li>校验 <code>api_path_patterns</code> 是否允许当前 servlet path</li></ol><p>失败：业务码 <strong>30002</strong>，HTTP <strong>401</strong>。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./oauth2.html" class="vp-link">OAuth2 集成</a></li><li><a href="./oauth2.html#联邦登录-client" class="vp-link">外部 IdP 提供方</a>（<code>sys_oauth_provider</code>）</li></ul>',16)])])}const _=e(c,[["render",i]]);export{p as __pageData,_ as default};
